import json, sys
data = json.load(sys.stdin)
# Show top-level structure
if isinstance(data, dict):
    for k, v in data.items():
        if k != 'document':
            print(f'{k}: {type(v).__name__}')
        else:
            print(f'document: {type(v).__name__}')
            if isinstance(v, dict):
                for dk, dv in v.items():
                    if dk == 'children':
                        print(f'  children: {len(dv)} items')
                        for i, child in enumerate(dv):
                            name = child.get('name', 'unnamed')
                            ctype = child.get('type', 'unknown')
                            x = child.get('x', '?')
                            y = child.get('y', '?')
                            w = child.get('width', '?')
                            h = child.get('height', '?')
                            cid = child.get('id', '?')
                            print(f'    [{i}] {ctype} \"{name}\" id={cid} pos=({x},{y}) size={w}x{h}')
                    else:
                        print(f'  {dk}: {dv}')
